<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>Maze Discovery Bots</title>
<style>
  body { font-family: sans-serif; background:#f4f4f4; text-align:center; margin:20px; }
  #maze { display:inline-block; border:2px solid #333; background:#fff; line-height:0; }
  canvas { display:block; width:600px; height:600px; }
  #stats { margin:10px; font-size:18px; }
  button { padding:8px 16px; font-size:16px; cursor:pointer; }
</style>
</head>
<body>
  <h1>Maze Discovery Bots</h1>
  <div id="stats">Completed: <span id="completed">0/24</span> | Ticks: <span id="timer">0</span></div>
  <button id="reset">Reset</button>
  <div id="maze"><canvas id="canvas" width="600" height="600"></canvas></div>
  <script>
  (function(){
    const ROWS = 21;
    const COLS = 21;
    const BOT_COUNT = 24;
    const DIRS = { n:{dr:-1,dc:0,opp:'s'}, e:{dr:0,dc:1,opp:'w'}, s:{dr:1,dc:0,opp:'n'}, w:{dr:0,dc:-1,opp:'e'} };
    const DNAMES = ['n','e','s','w'];

    let maze = [];
    const exit = {r:0,c:0};
    let bots = [];
    let allFinished = false;

    function mulberry32(a){
      return function(){
        a |= 0; a = a + 0x6D2B79F5 | 0;
        var t = Math.imul(a ^ a >>> 15, 1 | a);
        t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;
        return ((t ^ t >>> 14) >>> 0) / 4294967296;
      }
    }
    function randInt(rng, n){ return Math.floor(rng()*n); }
    function shuffle(arr, rng){
      for (let i=arr.length-1;i>0;i--){
        const j = randInt(rng, i+1);
        const tmp = arr[i]; arr[i] = arr[j]; arr[j] = tmp;
      }
      return arr;
    }
    function dirBetween(from, to){
      if (to.r < from.r) return 'n';
      if (to.r > from.r) return 's';
      if (to.c < from.c) return 'w';
      if (to.c > from.c) return 'e';
      return null;
    }

    function generateMaze(rng){
      const cells = [];
      for (let r=0;r<ROWS;r++){
        cells[r] = [];
        for (let c=0;c<COLS;c++){
          cells[r][c] = {n:true,e:true,s:true,w:true,visited:false};
        }
      }
      const stack = [{r:0,c:0}];
      cells[0][0].visited = true;
      while (stack.length){
        const cur = stack[stack.length-1];
        const opts = [];
        for (const d of DNAMES){
          const nr = cur.r + DIRS[d].dr, nc = cur.c + DIRS[d].dc;
          if (nr>=0 && nr<ROWS && nc>=0 && nc<COLS && !cells[nr][nc].visited) opts.push(d);
        }
        if (opts.length){
          const d = opts[randInt(rng, opts.length)];
          cells[cur.r][cur.c][d] = false;
          const nr = cur.r + DIRS[d].dr, nc = cur.c + DIRS[d].dc;
          cells[nr][nc][DIRS[d].opp] = false;
          cells[nr][nc].visited = true;
          stack.push({r:nr,c:nc});
        } else {
          stack.pop();
        }
      }
      const walls = [];
      for (let r=0;r<ROWS;r++){
        walls[r] = [];
        for (let c=0;c<COLS;c++){
          walls[r][c] = {n:cells[r][c].n,e:cells[r][c].e,s:cells[r][c].s,w:cells[r][c].w};
        }
      }
      return walls;
    }

    function chooseExit(rng){
      const dist = [];
      for (let r=0;r<ROWS;r++){ dist[r]=[]; for (let c=0;c<COLS;c++) dist[r][c]=-1; }
      const q = [{r:0,c:0}];
      dist[0][0] = 0;
      let head = 0;
      while (head < q.length){
        const cur = q[head++];
        for (const d of DNAMES){
          if (!maze[cur.r][cur.c][d]){
            const nr = cur.r + DIRS[d].dr, nc = cur.c + DIRS[d].dc;
            if (dist[nr][nc] === -1){
              dist[nr][nc] = dist[cur.r][cur.c] + 1;
              q.push({r:nr,c:nc});
            }
          }
        }
      }
      let best = -1;
      const far = [];
      for (let r=0;r<ROWS;r++){
        for (let c=0;c<COLS;c++){
          if (dist[r][c] > best){ best = dist[r][c]; far.length=0; far.push({r,c}); }
          else if (dist[r][c] === best){ far.push({r,c}); }
        }
      }
      return far[randInt(rng, far.length)];
    }

    class Bot {
      constructor(id, spawn, dirOrder, color){
        this.id = id;
        this.color = color;
        this.dirOrder = dirOrder;
        this.stack = [{r:spawn.r,c:spawn.c}];
        this.path = [{r:spawn.r,c:spawn.c}];
        this.deadEnds = [];
        this.deadSet = new Set();
        this.finishTick = null;
        this.marks = [];
        this.known = [];
        for (let r=0;r<ROWS;r++){
          this.marks[r] = [];
          this.known[r] = [];
          for (let c=0;c<COLS;c++){
            this.marks[r][c] = {n:0,e:0,s:0,w:0};
            this.known[r][c] = null;
          }
        }
        this.visualR = spawn.r;
        this.visualC = spawn.c;
      }
      step(){
        if (this.finishTick !== null) return;
        const cur = this.stack[this.stack.length-1];
        const known = this.known[cur.r][cur.c];
        let chosen = null;
        for (const d of this.dirOrder){
          if (known[d] === false && this.marks[cur.r][cur.c][d] === 0){
            chosen = d; break;
          }
        }
        if (chosen){
          const info = DIRS[chosen];
          const nr = cur.r + info.dr, nc = cur.c + info.dc;
          this.marks[cur.r][cur.c][chosen]++;
          this.marks[nr][nc][info.opp]++;
          this.known[nr][nc] = maze[nr][nc];
          const next = {r:nr,c:nc};
          this.stack.push(next);
          this.path.push(next);
        } else {
          if (this.stack.length > 1){
            const parent = this.stack[this.stack.length-2];
            const back = dirBetween(cur, parent);
            const key = cur.r + ',' + cur.c;
            if (!this.deadSet.has(key)){
              this.deadSet.add(key);
              this.deadEnds.push({r:cur.r,c:cur.c});
            }
            this.marks[cur.r][cur.c][back]++;
            this.marks[parent.r][parent.c][DIRS[back].opp]++;
            this.stack.pop();
            this.path.push({r:parent.r,c:parent.c});
          }
        }
      }
    }

    const game = {
      elapsed: 0,
      size: {rows: ROWS, cols: COLS},
      spawn: {r:0,c:0},
      exit: exit,
      walls: function(r,c){
        r = Math.floor(r); c = Math.floor(c);
        if (r<0||r>=ROWS||c<0||c>=COLS) return {n:true,e:true,s:true,w:true};
        const w = maze[r][c];
        return {n:!!w.n,e:!!w.e,s:!!w.s,w:!!w.w};
      },
      bots: bots,
      tick: function(n){
        if (allFinished) return;
        if (typeof n !== 'number') n = 1;
        n = Math.max(0, Math.floor(n));
        for (let i=0;i<n;i++){
          if (allFinished) break;
          const tickIndex = game.elapsed;
          for (const bot of bots){
            if (bot.finishTick === null) bot.step();
          }
          const newElapsed = tickIndex + 1;
          let stillSearching = false;
          for (const bot of bots){
            if (bot.finishTick === null){
              const cur = bot.stack[bot.stack.length-1];
              if (cur.r === exit.r && cur.c === exit.c){
                bot.finishTick = newElapsed;
              } else {
                stillSearching = true;
              }
            }
          }
          game.elapsed = newElapsed;
          if (!stillSearching) allFinished = true;
        }
      },
      reset: function(seed){
        if (typeof seed !== 'number') seed = Math.floor(Math.random()*1000000000);
        const rng = mulberry32(seed >>> 0);
        maze = generateMaze(rng);
        const ex = chooseExit(rng);
        exit.r = ex.r; exit.c = ex.c;
        bots.length = 0;
        allFinished = false;
        game.elapsed = 0;
        for (let i=0;i<BOT_COUNT;i++){
          const dirOrder = shuffle(['n','e','s','w'].slice(), rng);
          const color = 'hsl(' + ((i * 360 / BOT_COUNT) % 360) + ',80%,45%)';
          const bot = new Bot(i, game.spawn, dirOrder, color);
          bot.known[game.spawn.r][game.spawn.c] = maze[game.spawn.r][game.spawn.c];
          bots.push(bot);
        }
      }
    };
    window.game = game;

    const canvas = document.getElementById('canvas');
    const ctx = canvas.getContext('2d');

    function draw(){
      const W = canvas.width, H = canvas.height;
      const cw = W / COLS, ch = H / ROWS;
      ctx.fillStyle = '#ffffff';
      ctx.fillRect(0,0,W,H);

      ctx.fillStyle = '#d0e8ff';
      ctx.fillRect(game.spawn.c*cw, game.spawn.r*ch, cw, ch);
      ctx.fillStyle = '#b8f5c8';
      ctx.fillRect(exit.c*cw, exit.r*ch, cw, ch);

      ctx.strokeStyle = '#222';
      ctx.lineWidth = 2;
      ctx.lineCap = 'square';
      for (let r=0;r<ROWS;r++){
        for (let c=0;c<COLS;c++){
          const x = c*cw, y = r*ch;
          const w = maze[r][c];
          if (w.n){ ctx.beginPath(); ctx.moveTo(x,y); ctx.lineTo(x+cw,y); ctx.stroke(); }
          if (w.e){ ctx.beginPath(); ctx.moveTo(x+cw,y); ctx.lineTo(x+cw,y+ch); ctx.stroke(); }
          if (w.s){ ctx.beginPath(); ctx.moveTo(x,y+ch); ctx.lineTo(x+cw,y+ch); ctx.stroke(); }
          if (w.w){ ctx.beginPath(); ctx.moveTo(x,y); ctx.lineTo(x,y+ch); ctx.stroke(); }
        }
      }

      const radius = Math.min(cw,ch)/3.5;
      for (const bot of bots){
        const x = (bot.visualC + 0.5) * cw;
        const y = (bot.visualR + 0.5) * ch;
        ctx.beginPath();
        ctx.arc(x,y,radius,0,Math.PI*2);
        ctx.fillStyle = bot.color;
        ctx.fill();
        ctx.strokeStyle = '#000';
        ctx.lineWidth = 1;
        ctx.stroke();
      }

      let completed = 0;
      for (const bot of bots) if (bot.finishTick !== null) completed++;
      document.getElementById('completed').textContent = completed + '/' + BOT_COUNT;
      document.getElementById('timer').textContent = game.elapsed;
    }

    function animate(){
      for (const bot of bots){
        const cur = bot.stack[bot.stack.length-1];
        const dr = cur.r - bot.visualR;
        const dc = cur.c - bot.visualC;
        if (Math.abs(dr) > 0.001 || Math.abs(dc) > 0.001){
          bot.visualR += dr * 0.25;
          bot.visualC += dc * 0.25;
        } else {
          bot.visualR = cur.r;
          bot.visualC = cur.c;
        }
      }
      draw();
      requestAnimationFrame(animate);
    }

    document.getElementById('reset').addEventListener('click', function(){ game.reset(); });
    game.reset();
    animate();
  })();
  </script>
</body>
</html>
